; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxndotl (ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen)), starts in normal mode
; ============================================================

			OUTPUT "SHELSORT.DOT"		; the dot command (C:/DOT/SHELSORT.DOT: .shelsort at the BASIC prompt)
; ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen): NTC_ZXNDOT defined, and NTC_ZXNDOTL (the Large Model: the program from #8000, the Memory class's banks from NextZXOS's allocator - asm/ntc_lib_dot.asm)
			DEFINE NTC_ZXNDOT
			DEFINE NTC_ZXNDOTL
			org #2000

; ============================================================
; Platform start code (the platform's ntc_plat_romhead) - at the org, on to ntc_start
; ============================================================
; ------------------------------------------------------------
; The entry (the compiler puts this section first, at #2000) and the
; BASIC-side machinery: everything the ROM calls need, in one place, so
; that the Large Model (zxndotl) - which runs the program from #8000 in its
; own pages and keeps only this 8K in common with BASIC's memory - has it
; here too. Self-contained: no label from another section is named.
; ------------------------------------------------------------
dot_entry:
			di
			ld (dot_bsp), sp		; BASIC's stack: the ROM calls run on it, End returns on it
			ld (dot_hl), hl			; the arguments (0: none)
			ld (dot_bc), bc
			ld a, i
			ld (dot_iold), a		; BASIC's I (put back at the end)
			ld sp, dot_tstack		; a stack of our own for the rest of the entry
			call dot_cmdsave		; the arguments into ntc_cmdbuf before anything moves them
	IFDEF NTC_ZXNDOTL
			call dotl_setup			; the Large Model: its pages, the program read from this file
	ENDIF
			ld hl, dot_chan			; the upper screen is the channel printed to
			call dot_os
			ld a, dot_ivec >> 8		; IM 2, our handler (dot_irq) from here on, except inside dot_os
			ld i, a
			im 2
			jp ntc_start

; dot_cmdsave - (dot_hl) = the arguments: into ntc_cmdbuf, 0 ended, up to 127
; characters, up to #0D, ':' outside double quotes, or 0; leading spaces left out
dot_cmdsave:
			ld hl, (dot_hl)
			ld de, ntc_cmdbuf
			ld a, h
			or l
			jr z, dot_cs_end
			ld b, 127
			ld c, 0					; C = 1 inside quotes
dot_cs_sp:
			ld a, (hl)
			cp ' '
			jr nz, dot_cs_lp
			inc hl
			jr dot_cs_sp
dot_cs_lp:
			ld a, (hl)
			or a
			jr z, dot_cs_end
			cp #0D
			jr z, dot_cs_end
			cp '"'
			jr nz, dot_cs_nq
			ld a, c
			xor 1
			ld c, a
			ld a, '"'
dot_cs_nq:
			cp ':'
			jr nz, dot_cs_st
			bit 0, c
			jr z, dot_cs_end		; a ':' outside quotes ends the line
dot_cs_st:
			ld (de), a
			inc hl
			inc de
			djnz dot_cs_lp
dot_cs_end:
			xor a
			ld (de), a
			ret

; dot_os - HL = a routine (in this 8K) to run on BASIC's side: BASIC's stack,
; IY = ERR_NR (the ROM's), interrupts on (the ROM's keyboard scan, "scroll?"),
; and - the Large Model - BASIC's memory in slots 2-7. Back with interrupts
; off, our stack (SP as it was) and our memory; A, BC, DE, HL as the routine
; left them, IX kept. Call it on the real stack, never with SP in the thread
dot_os:
			ld (dot_osp), sp
			ld (dot_oix), ix
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack		; (the swap's calls: never on the program's stack, which is in a slot being swapped)
			push hl
			call dotl_bside			; slots 2-7 = BASIC's (ours noted)
			pop hl
	ENDIF
			ld sp, (dot_bsp)
			ld iy, #5C3A
			im 1					; the ROM's handler while the ROM runs
			ex de, hl
			ld hl, (#5C78)			; FRAMES now: its advance during the call is added to dot_frames
			ld (dot_fr0), hl
			ex de, hl
			ld de, dot_os_back
			push de
			ei
			jp (hl)
dot_os_back:
			di
			push af					; (the routine's result: A and the flags - dotl_alloc's carry)
			push hl
			push de
			ld hl, (#5C78)
			ld de, (dot_fr0)
			or a
			sbc hl, de
			ld de, (dot_frames)
			add hl, de
			ld (dot_frames), hl
			pop de
			pop hl
			pop af
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack
			push af
			push hl
			call dotl_oside			; slots 2-7 = ours again
			pop hl
			pop af
	ENDIF
			im 2
			ld sp, (dot_osp)
			ld ix, (dot_oix)
			ret

; ---- the BASIC-side routines (reached through dot_os only)
; dot_chan - the upper screen, channel 2, is the channel rst #10 prints to
dot_chan:
			ld a, 2
			rst #18
			dw #1601				; CHAN-OPEN
			ret
; dot_putc - (dot_ch) printed
dot_putc:
			ld a, (dot_ch)
			rst #10
			ret
; dot_cls - the ROM's CLS, then the channel again (CLS leaves the lower screen's)
dot_cls:
			rst #18
			dw #0D6B				; CLS
			jr dot_chan
; dot_at - AT (dot_row), (dot_col): the ROM's control code 22
dot_at:
			ld a, 22
			rst #10
			ld a, (dot_row)
			rst #10
			ld a, (dot_col)
			rst #10
			ret
; dot_wait - a frame: until the ROM's interrupt moves FRAMES on (not halt: a program
; that stops on halt can't be stepped by every harness - and the ROM's handler runs
; the same either way)
dot_wait:
			ld hl, #5C78			; FRAMES
			ld a, (hl)
dot_wt_lp:
			cp (hl)
			jr z, dot_wt_lp
			ret
; dot_kread - a frame's wait for the ROM's keyboard scan, then A = the new key
; (LAST_K, the FLAGS bit cleared) or 0
dot_kread:
			call dot_wait
			ld a, (#5C3B)			; FLAGS: bit 5 = a new key in LAST_K
			bit 5, a
			jr z, dot_kr_none
			res 5, a
			ld (#5C3B), a
			ld a, (#5C08)			; LAST_K
			ret
dot_kr_none:
			xor a
			ret

; ---- the entry's data
dot_bsp:		dw 0			; BASIC's SP at entry
dot_hl:			dw 0			; HL at entry: the arguments
dot_bc:			dw 0			; BC at entry: the whole command line
dot_osp:		dw 0			; dot_os: our SP
dot_oix:		dw 0			; dot_os: IX
dot_ch:			db 0			; the character for dot_putc
dot_row:		db 0			; dot_at: row, column (0 based)
dot_col:		db 0
dot_frames:		dw 0			; frames counted (dot_irq, plus FRAMES' advance in the ROM calls): Ticks
dot_fr0:		dw 0			; dot_os: FRAMES at the call's start
dot_iold:		db 0			; BASIC's I register
ntc_cmdbuf:		ds 128			; the arguments, 0 ended (System.CommandLine)
; dot_irq - the IM 2 handler: a frame counted. Only this 8K is touched (it runs with the
; program's memory in the slots and SP on the program's real stack)
dot_irq:
			push hl
			ld hl, (dot_frames)
			inc hl
			ld (dot_frames), hl
			pop hl
			ei
			reti
; the IM 2 vector table, 256-aligned: the Z80 reads its bytes #FF and #100 (the data bus
; gives #FF) - the handler's address; the rest is the entry's two stacks
			ALIGN 256
dot_ivec:
			ds 255 - 48
			ds 32
dot_tstack:						; the entry's own stack (32 bytes: the entry's calls only)
			ds 16
dot_xstack:						; dot_os's own (16 bytes: the slot swap's calls - the Large Model) = dot_ivec + #FF
			dw dot_irq				; the vector

	IFDEF NTC_ZXNDOTL
; ------------------------------------------------------------
; The Large Model (zxndotl): the program runs from #8000 in four 8K pages of
; its own, the Memory class's window #4000-#7FFF is two more, all allocated
; from NextZXOS (IDE_BANK through M_P3DOS) at entry and given back at the end;
; its banks (64K: 8 pages each) come from the same allocator at the Memory
; class's first call (ntc_lib_dot.asm). Slots 2-7 hold ours while the program
; runs, BASIC's while a ROM / esxDOS call runs (dot_os: dotl_bside / dotl_oside).
; The program itself is read from this file, after its first 8K (M_GETHANDLE:
; NextZXOS leaves the file open there), into #8000 on.
; ------------------------------------------------------------
DOTL_MAXPG	equ 6 + 8 * 16			; pages at most: the 6 base ones and 16 banks (1MB)
dotl_bslots:	ds 6			; BASIC's pages in slots 2-7 (NextRegs #52-#57 at entry)
dotl_oslots:	ds 6			; ours (slots 2-3 the window, 4-7 the program #8000-#FFFF), as last seen
dotl_scr:		ds 6			; (dotl_oside's reads)
dotl_npages:	db 0			; pages allocated (in dotl_pages)
dotl_pages:		ds DOTL_MAXPG	; their numbers: the 6 base ones, then the Memory class's 8 a bank
dotl_e:			db 0			; dotl_alloc: the page it got / dotl_free: the page to give back
dotl_hdl:		db 0			; this file's handle
dotl_err:		dw 0			; the message for the error return

; dotl_setup - (the entry, on dot_tstack, BASIC's memory) BASIC's slots noted, the 6
; base pages allocated and mapped, the program read into #8000 on. Doesn't return when
; it fails: the error return to BASIC with a message
dotl_setup:
			ld hl, dotl_bslots		; BASIC's pages in slots 2-7
			ld d, #52
dotl_su_rd:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)
			ld (hl), a
			inc hl
			inc d
			ld a, d
			cp #58
			jr nz, dotl_su_rd
			ld b, 6					; the 6 base pages
dotl_su_al:
			push bc
			call dotl_page			; one more into dotl_pages
			pop bc
			jr nc, dotl_su_nomem
			djnz dotl_su_al
			ld hl, dotl_pages		; ours: slots 2-3 pages 0, 1 (the window), 4-7 pages 2-5
			ld de, dotl_oslots
			ld bc, 6
			ldir
			call dotl_oside			; mapped (this 8K and the ROM stay: slots 0, 1)
			rst #08
			db #8D					; M_GETHANDLE: A = this file's handle, open after its first 8K
			ld (dotl_hdl), a
			ld hl, #8000
			ld bc, ntc_end - #8000	; the program (the file's end: no window data, no Skip on this platform)
			push bc
			rst #08
			db #9D					; F_READ: A = handle, HL = where, BC = how many
			pop hl
			jr c, dotl_su_short
			or a
			sbc hl, bc				; all of it?
			ret z
dotl_su_short:
			ld hl, dotl_m_short
			jr dotl_fail
dotl_su_nomem:
			ld hl, dotl_m_nomem
; dotl_fail - HL = the message (bit 7 on its last character): the pages back, BASIC's
; memory and stack, the esxDOS custom error return (carry set, A = 0, HL = the message)
dotl_fail:
			ld (dotl_err), hl
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld hl, (dotl_err)
			ld iy, #5C3A
			xor a
			scf
			ei
			ret
; dotl_exit - (End: ntc_plat_exit jumps here - this 8K stays mapped when slots 2-7 go
; back to BASIC's; the program's code doesn't) the pages given back, BASIC's memory and
; stack, carry clear (0 OK), interrupts on
dotl_exit:
			ld sp, dot_tstack
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld iy, #5C3A
			ld a, (dot_iold)
			ld i, a
			im 1
			or a
			ei
			ret
dotl_m_nomem:	db "Out of memory: no free 8K pages (IDE_BANK", ')' + #80
dotl_m_short:	db "The .DOT file is short: the program did not read in ful", 'l' + #80

; dotl_page - one page allocated (IDE_BANK, on BASIC's side) into dotl_pages: C = its
; number, carry set; carry clear when there is none (or no room in dotl_pages)
dotl_page:
			ld a, (dotl_npages)
			cp DOTL_MAXPG
			ret nc					; (carry clear: full)
			ld hl, dotl_alloc
			call dot_os				; carry set = got one, (dotl_e) = it
			ret nc
			ld hl, dotl_pages
			ld a, (dotl_npages)
			ld e, a
			ld d, 0
			add hl, de
			ld a, (dotl_e)
			ld (hl), a
			ld c, a
			ld a, (dotl_npages)
			inc a
			ld (dotl_npages), a
			scf
			ret
; dotl_freeall - every page in dotl_pages given back (IDE_BANK free, on BASIC's side)
dotl_freeall:
			ld a, (dotl_npages)
			or a
			ret z
			ld b, a
			ld hl, dotl_pages
dotl_fa_lp:
			ld a, (hl)
			ld (dotl_e), a
			push bc
			push hl
			ld hl, dotl_free
			call dot_os
			pop hl
			pop bc
			inc hl
			djnz dotl_fa_lp
			xor a
			ld (dotl_npages), a
			ret

; dotl_bside - slots 2-7 = BASIC's pages, ours noted first (dotl_oslots)
; dotl_oside - slots 2-7 = ours again
; (from code in this 8K, on a stack in it: slots 2-7 change under anything else)
dotl_bside:
			ld hl, dotl_oslots
			ld ix, dotl_bslots
			jr dotl_swap
dotl_oside:
			ld hl, dotl_scr
			ld ix, dotl_oslots
dotl_swap:
			ld d, #52
dotl_sw_lp:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)				; the page there now
			ld (hl), a
			ld a, (ix + 0)
			out (c), a				; the page to be
			inc hl
			inc ix
			inc d
			ld a, d
			cp #58
			jr nz, dotl_sw_lp
			ret

; ---- BASIC-side (dot_os): the allocator, M_P3DOS's IDE_BANK (#01BD): H = 0 a ZX 8K
; page, L = 1 allocate / 3 free (E = the page), the call's registers in the alternate
; set; carry SET = done, E = the page
dotl_alloc:
			ld hl, #0001
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94					; M_P3DOS
			ld a, e
			ld (dotl_e), a
			ret
dotl_free:
			ld a, (dotl_e)
			ld e, a
			ld hl, #0003
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94
			ret
	ENDIF

			ASSERT $ <= #4000, "the dot command's entry code and data must fit in #2000-#3FFF"
			ds #4000 - $			; the first 8K of the file, padded
			OPT -Wno-fileorg		; (the file goes on where the 8K ends: the org below is where the program runs, not a gap)
			org #8000			; the program: read into its own pages by the entry

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, 0		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 14: Input "How many numbers (Return = 2000)"; n
			dw kw_printstrvar, str0
			dw kw_inputint, var_n

			; main.bas 15: If n < 10 Or n > MAXN Then n = MAXN
			dw kw_scpltvl, var_n, 10
			dw kw_ftov, tmp0
			dw kw_scpgtvl, var_n, 2000
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if1_1
			dw kw_ltov, 2000, var_n
if1_1:

			; main.bas 16: Do
do2_t:

			; main.bas 17: Print
			dw kw_printnl

			; main.bas 18: Print "T = turbo, N = normal, X = exit"
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 19: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dw kw_inkeys, stmp0
			dw kw_strucase, var_k, stmp0
			dw kw_frame
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_strcmpeq, var_k, str4
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, do3_t
do3_e:

			; main.bas 20: If k = "X" Then Exit Do
			dw kw_strcmpeq, var_k, str4
			dw kw_goto_iffalse_n, if4_1
			dw do2_e_go
if4_1:

			; main.bas 22: Randomize 7
			dw kw_seedl, 7

			; main.bas 23: For i = 0 To n
			dw kw_ztov, var_i
			dw kw_vtov, var_n, for5_l
			dw kw_forupv_n, var_i, for5_l, for5_e
for5_t:

			; main.bas 24: a(i) = Rnd(1000)
			dw kw_rndl, 1000, tmp1
			dw kw_aset, arr_a, var_i, tmp1

			; main.bas 25: Next
			dw kw_next1v_n, var_i, for5_l, for5_t
for5_e:

			; main.bas 26: Print IIf(k = "T", "Turbo", "Normal"); ": sorting "; n + 1; " numbers..."
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch6_0
			dw kw_strcpy, stmp0, str5
			dw ch6_e_go
ch6_0:
			dw kw_strcpy, stmp0, str6
			dw ch6_e_go
ch6_1:
			dw kw_strcpy, stmp0, str7
ch6_e:
			dw kw_printstrvar, stmp0
			dw kw_addl, var_n, 1, tmp0
			dw kw_printstrvar, str8
			dw kw_printint, tmp0
			dw kw_printstrvar, str9
			dw kw_printnl

			; main.bas 27: t0 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t0

			; main.bas 28: If k = "T" Then
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, if7_1

			; main.bas 29: Turbo On
			dw kw_turbo_on

			; main.bas 30: ShellSort
			dw p_shellsort_c

			; main.bas 31: Turbo Off
			dw kw_turbo_off

			; main.bas 32: Else
			dw if7_e_go
if7_1:

			; main.bas 33: ShellSort
			dw p_shellsort_n_c

			; main.bas 34: End If
if7_e:

			; main.bas 35: t1 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t1

			; main.bas 36: Print "Done - stop the stopwatch"
			dw kw_printstrvar, str10
			dw kw_printnl

			; main.bas 37: For i = 0 To 9
			dw kw_ztov, var_i
for8_t:

			; main.bas 38: Print a(i); " ";
			dw kw_aget, arr_a, var_i, tmp0
			dw kw_printint, tmp0
			dw kw_printstrvar, str11

			; main.bas 39: Next
			dw kw_next1l_n, var_i, 9, for8_t
for8_e:

			; main.bas 40: Print
			dw kw_printnl

			; main.bas 41: If (k = "N") And (System.TicksPerSecond > 0) Then
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, if9_1

			; main.bas 42: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_printstrvar, str12
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_divvl, tmp0, 50, tmp0
			dw kw_printstrvar, str13
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_modvl, tmp0, 50, tmp0
			dw kw_mulvl, tmp0, 10, tmp0
			dw kw_divvl, tmp0, 50, tmp0
			dw kw_printstrvar, str14
			dw kw_printint, tmp0
			dw kw_printstrvar, str15
			dw kw_printnl

			; main.bas 43: ElseIf k = "T" Then
			dw do2_t_go
if9_1:
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, do2_t

			; main.bas 44: Print "(turbo runs with interrupts off, so"
			dw kw_printstrvar, str16
			dw kw_printnl

			; main.bas 45: Print "time it with the stopwatch)"
			dw kw_printstrvar, str17
			dw kw_printnl

			; main.bas 46: End If
if9_2:
if9_e:

			; main.bas 47: Loop
			dw do2_t_go
do2_e:

			; main.bas 48: End
			dw kw_printnl0
			dw kw_printstrvar, str18
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub shellsort (turbo mode)
; ============================================================

p_shellsort:

			; main.bas 51: Dim gap As Integer, i As Integer, j As Integer, t As Integer

			; main.bas 52: gap = n \ 2
			dw kw_divvl, var_n, 2, var_shellsort_gap

			; main.bas 53: Do While gap > 0
do10_t:
			dw kw_scpgtvl, var_shellsort_gap, 0
			dw kw_goto_iffalse, do10_e

			; main.bas 54: For i = gap To n
			dw kw_vtov, var_shellsort_gap, var_shellsort_i
			dw kw_vtov, var_n, for11_l
			dw kw_forupv, var_shellsort_i, for11_l, for11_e
for11_t:

			; main.bas 55: t = a(i)
			dw kw_aget, arr_a, var_shellsort_i, var_shellsort_t

			; main.bas 56: j = i
			dw kw_vtov, var_shellsort_i, var_shellsort_j

			; main.bas 57: Do While j >= gap
do12_t:
			dw kw_scpgevv, var_shellsort_j, var_shellsort_gap
			dw kw_goto_iffalse, do12_e

			; main.bas 58: If a(j - gap) <= t Then Exit Do
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp0
			dw kw_aget, arr_a, tmp0, tmp0
			dw kw_scplevv, tmp0, var_shellsort_t
			dw kw_goto_iffalse, if13_1
			dw do12_e_go
if13_1:

			; main.bas 59: a(j) = a(j - gap)
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp1
			dw kw_aget, arr_a, tmp1, tmp1
			dw kw_aset, arr_a, var_shellsort_j, tmp1

			; main.bas 60: j = j - gap
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, var_shellsort_j

			; main.bas 61: Loop
			dw do12_t_go
do12_e:

			; main.bas 62: a(j) = t
			dw kw_aset, arr_a, var_shellsort_j, var_shellsort_t

			; main.bas 63: Next
			dw kw_next1v, var_shellsort_i, for11_l, for11_t
for11_e:

			; main.bas 64: gap = gap \ 2
			dw kw_divvl, var_shellsort_gap, 2, var_shellsort_gap

			; main.bas 65: Loop
			dw do10_t_go
do10_e:
			dw p_shellsort_r

; ============================================================
; sub shellsort (normal mode)
; ============================================================

p_shellsort_n:

			; main.bas 51: Dim gap As Integer, i As Integer, j As Integer, t As Integer

			; main.bas 52: gap = n \ 2
			dw kw_divvl, var_n, 2, var_shellsort_gap

			; main.bas 53: Do While gap > 0
do14_t:
			dw kw_scpgtvl, var_shellsort_gap, 0
			dw kw_goto_iffalse_n, do14_e

			; main.bas 54: For i = gap To n
			dw kw_vtov, var_shellsort_gap, var_shellsort_i
			dw kw_vtov, var_n, for15_l
			dw kw_forupv_n, var_shellsort_i, for15_l, for15_e
for15_t:

			; main.bas 55: t = a(i)
			dw kw_aget, arr_a, var_shellsort_i, var_shellsort_t

			; main.bas 56: j = i
			dw kw_vtov, var_shellsort_i, var_shellsort_j

			; main.bas 57: Do While j >= gap
do16_t:
			dw kw_scpgevv, var_shellsort_j, var_shellsort_gap
			dw kw_goto_iffalse_n, do16_e

			; main.bas 58: If a(j - gap) <= t Then Exit Do
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp0
			dw kw_aget, arr_a, tmp0, tmp0
			dw kw_scplevv, tmp0, var_shellsort_t
			dw kw_goto_iffalse_n, if17_1
			dw do16_e_go
if17_1:

			; main.bas 59: a(j) = a(j - gap)
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, tmp1
			dw kw_aget, arr_a, tmp1, tmp1
			dw kw_aset, arr_a, var_shellsort_j, tmp1

			; main.bas 60: j = j - gap
			dw kw_subvv, var_shellsort_j, var_shellsort_gap, var_shellsort_j

			; main.bas 61: Loop
			dw do16_t_go
do16_e:

			; main.bas 62: a(j) = t
			dw kw_aset, arr_a, var_shellsort_j, var_shellsort_t

			; main.bas 63: Next
			dw kw_next1v_n, var_shellsort_i, for15_l, for15_t
for15_e:

			; main.bas 64: gap = gap \ 2
			dw kw_divvl, var_shellsort_gap, 2, var_shellsort_gap

			; main.bas 65: Loop
			dw do14_t_go
do14_e:
			dw p_shellsort_n_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_e_go:			ld sp, do2_e
			jp ntc_xn
ch6_e_go:			ld sp, ch6_e
			jp ntc_xn
if7_e_go:			ld sp, if7_e
			jp ntc_xn
do2_t_go:			ld sp, do2_t
			jp ntc_xn
do12_e_go:			ld sp, do12_e
			ret
do12_t_go:			ld sp, do12_t
			ret
do10_t_go:			ld sp, do10_t
			ret
do16_e_go:			ld sp, do16_e
			jp ntc_xn
do16_t_go:			ld sp, do16_t
			jp ntc_xn
do14_t_go:			ld sp, do14_t
			jp ntc_xn

p_shellsort_c:		; call shellsort (turbo)
			ld hl, 0
			ld (var_shellsort_gap), hl
			ld (var_shellsort_i), hl
			ld (var_shellsort_j), hl
			ld (var_shellsort_t), hl
			ld (p_shellsort_rs), sp
			ld sp, p_shellsort
			ret
p_shellsort_r:		; end of shellsort
			ld sp, (p_shellsort_rs)
			ret
p_shellsort_n_c:		; call shellsort (normal)
			ld hl, 0
			ld (var_shellsort_gap), hl
			ld (var_shellsort_i), hl
			ld (var_shellsort_j), hl
			ld (var_shellsort_t), hl
			ld (p_shellsort_rs), sp
			ld sp, p_shellsort_n
			jp ntc_xn
p_shellsort_n_r:		; end of shellsort
			ld sp, (p_shellsort_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
			db 40			; capacity
var_k:			ds 41
var_i:			dw 0
for5_l:			dw 0
var_t0:			dw 0
var_t1:			dw 0
p_shellsort_rs:			dw 0
var_shellsort_gap:			dw 0
var_shellsort_i:			dw 0
var_shellsort_j:			dw 0
var_shellsort_t:			dw 0
for11_l:			dw 0
for15_l:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 40			; capacity
stmp0:			ds 41

; ============================================================
; Strings
