str0:			db "How many numbers (Return = 2000)? ", 0
str1:			db "T = turbo, N = normal, X = exit", 0
str2:			db "T", 0
str3:			db "N", 0
str4:			db "X", 0
str5:			db "Turbo", 0
str6:			db "Normal", 0
str7:			db 0
str8:			db ": sorting ", 0
str9:			db " numbers...", 0
str10:			db "Done - stop the stopwatch", 0
str11:			db " ", 0
str12:			db "took ", 0
str13:			db " ticks = ", 0
str14:			db ".", 0
